145	fn strip_tables(text: &str) -> String {
146	    text.lines()
147	        .filter(|line| {
148	            let t = line.trim();
149	            !(t.starts_with('|') && t.ends_with('|'))
150	        })
151	        .collect::<Vec<_>>()
152	        .join("\n")
153	}
