    fn snap_scroll_pins_oversized_items_to_their_start() {
        // Three selectables: [0,5), [5,50) (45 lines — taller than the
        // h=10 screen), [50,60).
        let starts = vec![0, 5, 50];
        let mut scroll = 0;
