144	fn tui_loop(stdout: &mut impl Write, repos: &mut Vec<Repository>, has_cd: bool, start_repo: Option<usize>) -> Result<Option<TuiOutcome>> {
145	    let current_repo_idx = find_repo_for_cwd(repos);
146	    let current_repo_dir: Option<String> = current_repo_idx
147	        .and_then(|i| repos.get(i))
148	        .map(|r| r.directory.clone());
149	
150	    let start_sel = current_repo_idx.unwrap_or(0);
151	
152	    // Navigation stack — back pops; when empty the TUI exits.
153	    // When starting inside a tracked repo, seed the stack with the repos list
154	    // underneath so pressing Back always returns to it rather than exiting.
155	    let mut stack: Vec<Screen> = if let Some(idx) = start_repo.filter(|&i| i < repos.len()) {
156	        let sessions = session_list::fetch(Scope::Repo(&repos[idx]), true);
157	        let worktrees = fetch_worktrees(&repos[idx].directory);
158	        vec![
159	            Screen::Repos { sel: idx },
160	            Screen::Sessions { repo_idx: idx, sel: 0, sessions, worktrees },
161	        ]
162	    } else {
163	        vec![Screen::Repos { sel: start_sel }]
164	    };
