166	    let mut awaiting_delete = false;
167	    let mut flash: Option<&'static str> = None;
168	
169	    // Commands produced inside match arms, executed after the borrow ends.
170	    enum Cmd {
171	        None,
172	        Break,
173	        Back,
174	        PushSessions(usize),
175	        Cd(String),
176	        ShowSession(String),
177	        ResumeSession(String, String), // (session_id, repo_dir)
178	        DeleteSession(String),         // session_id
179	        Discover,
180	        Search(String),
181	        NewWorktree(String), // branch name
182	        NewSession(NewSessionConfig),
183	        Tidy,
184	        Redraw,
185	    }
