187	    loop {
188	        let (w, h) = terminal::size().unwrap_or((120, 40));
189	        let w = w as usize;
190	        let h = h as usize;
191	
192	        match stack.last().unwrap() {
193	            Screen::Repos { sel } => draw_repos(stdout, repos, *sel, current_repo_dir.as_deref(), w, h, has_cd)?,
194	            Screen::Sessions { repo_idx, sel, sessions, worktrees } => {
195	                draw_sessions(stdout, repos, *repo_idx, sessions, worktrees, *sel, w, h, flash)?
196	            }
197	        }
