199	        let cmd = match event::read()? {
200	            Event::Key(k) => match stack.last_mut().unwrap() {
201	                Screen::Repos { sel } => match k.code {
202	                    KeyCode::Char('q') => Cmd::Break,
203	                    KeyCode::Esc => Cmd::Back,
204	                    KeyCode::Char('c') if k.modifiers.contains(crossterm::event::KeyModifiers::CONTROL) => {
