207	                        std::process::exit(0);
208	                    }
209	                    KeyCode::Up   | KeyCode::Char('k') => { if *sel > 0 { *sel -= 1; } Cmd::None }
210	                    KeyCode::Down | KeyCode::Char('j') => { if *sel + 1 < repos.len() { *sel += 1; } Cmd::None }
211	                    KeyCode::Char('g') => { *sel = 0; Cmd::None }
212	                    KeyCode::Char('G') => { *sel = repos.len().saturating_sub(1); Cmd::None }
213	                    KeyCode::Char(' ') | KeyCode::Right => Cmd::PushSessions(*sel),
214	                    KeyCode::Char('c') if has_cd => Cmd::Cd(repos[*sel].directory.clone()),
215	                    KeyCode::Char('s') => {
216	                        let repo_dir = repos[*sel].directory.clone();
217	                        match new_session_wizard(stdout, &repo_dir, w, h) {
218	                            Some(cfg) => Cmd::NewSession(cfg),
219	                            None => Cmd::Redraw,
