261	                        _ => Cmd::Redraw,
262	                    },
263	                    KeyCode::Char('n') => match super::collect_text_input(stdout, "  new worktree branch: ", w, h) {
264	                        Some(b) if !b.trim().is_empty() => Cmd::NewWorktree(b.trim().to_string()),
265	                        _ => Cmd::Redraw,
266	                    },
267	                    KeyCode::Char('s') => {
268	                        let repo_dir = repos[*repo_idx].directory.clone();
269	                        match new_session_wizard(stdout, &repo_dir, w, h) {
270	                            Some(cfg) => Cmd::NewSession(cfg),
271	                            None => Cmd::Redraw,
272	                        }
273	                    }
274	                    KeyCode::Char('t') => Cmd::Tidy,
275	                    _ => { awaiting_delete = false; flash = None; Cmd::None }
276	                },
277	            },
278	            Event::Resize(_, _) => Cmd::Redraw,
279	            _ => Cmd::None,
280	        };
281	
282	        match cmd {
283	            Cmd::None => {}
284	            Cmd::Break => return Ok(Some(TuiOutcome::Quit)),
285	            Cmd::Back => {
286	                stack.pop();
287	                if stack.is_empty() { break; }
288	            }
289	            Cmd::PushSessions(idx) => {
290	                let sessions = session_list::fetch(Scope::Repo(&repos[idx]), true);
291	                let worktrees = fetch_worktrees(&repos[idx].directory);
292	                stack.push(Screen::Sessions { repo_idx: idx, sel: 0, sessions, worktrees });
293	            }
294	            Cmd::Cd(path) => return Ok(Some(TuiOutcome::CdTo(path))),
295	            Cmd::ResumeSession(id, cwd) => return Ok(Some(TuiOutcome::ResumeSession { id, cwd })),
296	            Cmd::DeleteSession(id) => {
297	                super::clean::remove_session(&id).ok();
298	                if let Some(Screen::Sessions { sel, sessions, .. }) = stack.last_mut() {
299	                    sessions.retain(|s| s.session_id != id);
300	                    if *sel >= sessions.len() && !sessions.is_empty() { *sel = sessions.len() - 1; }
301	                }
302	                execute!(stdout, terminal::Clear(ClearType::All)).ok();
303	            }
304	            Cmd::ShowSession(id) => {
305	                execute!(stdout, LeaveAlternateScreen, cursor::Show).ok();
306	                terminal::disable_raw_mode().ok();
307	                let result = super::show::run(&id);
308	                terminal::enable_raw_mode().ok();
309	                execute!(stdout, EnterAlternateScreen, cursor::Hide).ok();
310	                execute!(stdout, terminal::Clear(ClearType::All)).ok();
311	                match result {
312	                    Ok(true) => return Ok(Some(TuiOutcome::Quit)),
313	                    Err(_) => { flash = Some("  Transcript not found — run `entire gossamer ingest` to backfill  "); }
314	                    Ok(false) => {}
315	                }
316	            }
317	            Cmd::Search(query) => {
318	                execute!(stdout, LeaveAlternateScreen, cursor::Show).ok();
319	                terminal::disable_raw_mode().ok();
320	                let quit_app = super::search::run(&query, 10, false).unwrap_or(false);
321	                terminal::enable_raw_mode().ok();
322	                if quit_app { return Ok(Some(TuiOutcome::Quit)); }
323	                execute!(stdout, EnterAlternateScreen, cursor::Hide).ok();
324	                execute!(stdout, terminal::Clear(ClearType::All)).ok();
325	            }
326	            Cmd::NewWorktree(branch) => {
327	                if let Some(Screen::Sessions { repo_idx, worktrees, .. }) = stack.last_mut() {
328	                    let repo_dir = &repos[*repo_idx].directory;
329	                    let notification = create_worktree(repo_dir, &branch);
330	                    // Refresh the worktree list whether or not it succeeded.
331	                    *worktrees = fetch_worktrees(repo_dir);
332	                    // Show the result in the status bar until the next keypress.
333	                    let (tw, th) = terminal::size().unwrap_or((120, 40));
334	                    let msg: String = notification.chars().take(tw as usize).collect();
335	                    let padded = format!("{:<width$}", msg, width = tw as usize);
336	                    execute!(stdout, cursor::MoveTo(0, th - 1)).ok();
337	                    write!(stdout, "\x1b[7m{padded}\x1b[0m").ok();
338	                    stdout.flush().ok();
339	                }
340	            }
341	            Cmd::NewSession(cfg) => {
342	                return Ok(Some(TuiOutcome::LaunchNewSession(cfg)));
343	            }
344	            Cmd::Tidy => {
345	                let repo_idx_opt = if let Some(Screen::Sessions { repo_idx, .. }) = stack.last() {
346	                    Some(*repo_idx)
347	                } else {
348	                    None
349	                };
350	                if let Some(repo_idx) = repo_idx_opt {
351	                    let repo = &repos[repo_idx];
352	                    let (tw, th) = terminal::size().unwrap_or((120, 40));
353	                    let changed = super::tidy::tui_tidy(
354	                        stdout,
355	                        std::slice::from_ref(repo),
356	                        7,
357	                        false,
358	                        tw as usize,
359	                        th as usize,
360	                    );
361	                    if changed {
362	                        if let Some(Screen::Sessions { worktrees, .. }) = stack.last_mut() {
363	                            *worktrees = fetch_worktrees(&repos[repo_idx].directory);
364	                        }
365	                    }
366	                    execute!(stdout, terminal::Clear(ClearType::All)).ok();
367	                }
368	            }
369	            Cmd::Redraw => { execute!(stdout, terminal::Clear(ClearType::All)).ok(); }
370	            Cmd::Discover => {
371	                let (tw, th) = terminal::size().unwrap_or((120, 40));
372	                let scanning = format!("{:<width$}", "  Scanning for new repos…", width = tw as usize);
373	                execute!(stdout, cursor::MoveTo(0, th - 1)).ok();
374	                write!(stdout, "\x1b[7m{scanning}\x1b[0m").ok();
375	                stdout.flush().ok();
376	
377	                let known: std::collections::HashSet<String> = repos.iter().map(|r| r.directory.clone()).collect();
378	                let candidates = super::discover::scan_candidates(&known);
379	
380	                if candidates.is_empty() {
381	                    let msg = format!("{:<width$}", "  No new GitHub repos found in Claude session history — press any key  ", width = tw as usize);
382	                    execute!(stdout, cursor::MoveTo(0, th - 1)).ok();
383	                    write!(stdout, "\x1b[7m{msg}\x1b[0m").ok();
384	                    stdout.flush().ok();
385	                    event::read().ok();
386	                } else if let Some(selected) = super::discover::tui_discover(stdout, candidates, tw as usize, th as usize) {
387	                    if !selected.is_empty() {
388	                        if let Ok(conn) = crate::db::connect() {
389	                            super::discover::register_and_backfill(&conn, &selected).ok();
390	                            if let Ok(new_repos) = fetch_repos(&conn) {
391	                                *repos = new_repos;
392	                            }
393	                        }
394	                    }
395	                }
396	                execute!(stdout, terminal::Clear(ClearType::All)).ok();
397	            }
398	        }
399	    }
400	
401	    Ok(None)
402	}
