406	fn draw_repos(
407	    stdout: &mut impl Write,
408	    repos: &[Repository],
409	    sel: usize,
410	    current_repo_dir: Option<&str>,
411	    w: usize,
412	    h: usize,
413	    has_cd: bool,
414	) -> io::Result<()> {
415	    use crossterm::queue;
416	    let t = crate::theme::get();
417	    let content_h = h.saturating_sub(1);
418	    let mut buf: Vec<u8> = Vec::with_capacity((w + 40) * (h + 2));
419	    let mut row = 0usize;
420	
421	    let name_w = repos.iter().map(|r| r.name.chars().count()).max().unwrap_or(0);
422	    let dir_w  = repos.iter().map(|r| r.directory.chars().count()).max().unwrap_or(0);
423	
424	    for (i, repo) in repos.iter().enumerate() {
425	        if row >= content_h { break }
426	
427	        let is_sel = i == sel;
428	        let is_cur = current_repo_dir == Some(repo.directory.as_str());
429	        let star = if is_cur {
430	            format!("\x1b[{}m★\x1b[0m", t.fresh)
431	        } else {
432	            " ".to_string()
433	        };
434	
435	        let name_padded = format!("{:<name_w$}", repo.name);
436	        let dir_padded  = format!("{:<dir_w$}",  repo.directory);
437	        let line = format!(
438	            "{star} \x1b[{pm}m{name_padded}\x1b[0m  \x1b[{dm}m{dir_padded}  {}\x1b[0m",
439	            repo.remote, pm = t.text_primary, dm = t.text_dim,
440	        );
441	
442	        super::render_row(&mut buf, &line, is_sel, row, w)?;
443	        row += 1;
444	    }
445	
446	    while row < content_h {
447	        queue!(buf, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine))?;
448	        row += 1;
449	    }
450	
451	    let cd_hint = if has_cd { "   c: cd" } else { "" };
452	    let bar = format!(
453	        "  {} repos   ↑↓/jk navigate   space: sessions   s: launch   d: discover   / search{}   q: quit  ",
454	        repos.len(), cd_hint
455	    );
456	    super::draw_statusbar(&mut buf, &bar, w, h)?;
457	
458	    stdout.write_all(&buf)?;
459	    stdout.flush()
460	}
