462	fn draw_sessions(
463	    stdout: &mut impl Write,
464	    repos: &[Repository],
465	    repo_idx: usize,
466	    sessions: &[RepoSession],
467	    worktrees: &[RepoWorktree],
468	    sel: usize,
469	    w: usize,
470	    h: usize,
471	    flash: Option<&str>,
472	) -> io::Result<()> {
473	    use crossterm::queue;
474	    let t = crate::theme::get();
475	    let content_h = h.saturating_sub(2); // header + status bar
476	    let mut buf: Vec<u8> = Vec::with_capacity((w + 40) * (h + 2));
477	
478	    // Header row
479	    queue!(buf, cursor::MoveTo(0, 0), terminal::Clear(ClearType::UntilNewLine))?;
480	    write!(buf, "\x1b[{hd}m{}\x1b[0m", repos[repo_idx].name, hd = t.header)?;
481	    let mut row = 1usize;
482	
483	    // ── Worktrees ────────────────────────────────────────────────────────────
484	    if !worktrees.is_empty() {
485	        for wt in worktrees.iter().take(content_h.saturating_sub(row + 1)) {
486	            if row >= content_h { break; }
487	
488	            let (branch_col, branch_label) = if wt.branch == "(detached)" {
489	                (t.error, format!("detached:{}", &wt.head))
490	            } else if wt.is_main {
491	                (t.accent, wt.branch.clone())
492	            } else {
493	                (t.link, wt.branch.clone())
494	            };
495	
496	            let path_short = super::short_path(&wt.path);
497	            let line = format!(
498	                "\x1b[{dm}m  @ \x1b[{branch_col}m{branch_label}\x1b[0m  \x1b[{dm}m{path_short}\x1b[0m",
499	                dm = t.text_dim,
500	            );
501	            queue!(buf, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine))?;
502	            write!(buf, "{line}")?;
503	            row += 1;
504	        }
505	
506	        if row < content_h {
507	            queue!(buf, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine))?;
508	            row += 1;
509	        }
510	    }
511	
512	    // ── Sessions ─────────────────────────────────────────────────────────────
513	    let sessions_start = row;
514	    let sessions_h = content_h.saturating_sub(sessions_start);
515	    // One row of sessions_h is consumed by the "session / branch / ..." header
516	    // drawn below, so only sessions_h - 1 rows are actually available for
517	    // entries. Without this, the scroll math thinks one more row is visible
518	    // than actually is, so the entry at the bottom edge computes as in view
519	    // but gets drawn past content_h and is dropped by the `row >= content_h`
520	    // break below — the highlighted row can end up off-screen.
521	    let entries_h = sessions_h.saturating_sub(1);
522	    let scroll = if sel >= entries_h { sel + 1 - entries_h } else { 0 };
523	
524	    if sessions.is_empty() {
525	        if row < content_h {
526	            queue!(buf, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine))?;
527	            write!(buf, "\x1b[{dm}m  no sessions found\x1b[0m", dm = t.text_dim)?;
528	            row += 1;
529	        }
530	    } else {
531	        let name_w   = sessions.iter().map(|s| s.session_name.trim().chars().count()).max().unwrap_or(0).min(40);
532	        let branch_w = sessions.iter().map(|s| s.branch.chars().count()).max().unwrap_or(0);
533	        let author_w = sessions.iter().map(|s| s.author.chars().count()).max().unwrap_or(0);
534	        let tokens_w = {
535	            let w = sessions.iter().map(|s| session_list::fmt_tokens(s.tokens_used).chars().count()).max().unwrap_or(0);
536	            if w > 0 { w.max(6) } else { 0 }
537	        };
538	
539	        if row < content_h {
540	            let dm = t.text_dim;
541	            let mut hdr = format!("  {:<name_w$}", "session");
542	            if branch_w > 0 { hdr.push_str(&format!("  {:<branch_w$}", "branch")); }
543	            if author_w > 0 { hdr.push_str(&format!("  {:<author_w$}", "author")); }
544	            if tokens_w > 0 { hdr.push_str(&format!("  {:>tokens_w$}", "tokens")); }
545	            hdr.push_str("  id        updated");
546	            let display: String = hdr.chars().take(w).collect();
547	            queue!(buf, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine))?;
548	            write!(buf, "\x1b[{dm}m{display}\x1b[0m")?;
549	            row += 1;
550	        }
551	
552	        for (i, s) in sessions.iter().enumerate().skip(scroll) {
553	            if row >= content_h { break; }
554	
555	            let id_short: String = s.session_id.chars().take(8).collect();
556	            let ts = relative_time(s.updated_at);
557	            let clean = session_list::sanitize_one_line(&s.session_name);
558	            let name: String = clean.chars().take(name_w).collect();
559	            let age = (Utc::now() - s.updated_at).num_seconds().max(0);
560	            let dot_col = match age {
561	                a if a < 900   => t.fresh,
562	                a if a < 3_600 => t.moderate,
563	                _              => t.text_dim,
564	            };
565	
566	            let (meta_col, dot_char) = if s.backed_up {
567	                (t.backed_meta, "★")
568	            } else {
569	                (t.unbacked_meta, "·")
570	            };
571	            let name_col = if s.name_is_explicit {
572	                t.backed_name
573	            } else if s.backed_up {
574	                t.text_secondary
575	            } else {
576	                t.unbacked_name
577	            };
578	            let branch_col = if s.backed_up { t.link } else { t.stale };
579	
580	            let name_padded = format!("{:<name_w$}", name);
581	            let mut line = format!("\x1b[{dot_col}m{dot_char}\x1b[0m \x1b[{name_col}m{name_padded}\x1b[0m");
582	
583	            if branch_w > 0 {
584	                let b: String = s.branch.chars().take(branch_w).collect();
585	                let pad = " ".repeat(branch_w - b.chars().count());
586	                line.push_str(&format!("  \x1b[{branch_col}m{b}{pad}\x1b[0m"));
587	            }
588	
589	            if author_w > 0 {
590	                let a: String = s.author.chars().take(author_w).collect();
591	                let pad = " ".repeat(author_w - a.chars().count());
592	                line.push_str(&format!("  \x1b[{dm}m{a}{pad}\x1b[0m", dm = t.text_dim));
593	            }
594	
595	            if tokens_w > 0 {
596	                let tok = session_list::fmt_tokens(s.tokens_used);
597	                let pad = " ".repeat(tokens_w - tok.chars().count());
598	                let tk = session_list::token_color(s.tokens_used);
599	                line.push_str(&format!("  \x1b[{dm}m{pad}\x1b[{tk}m{tok}\x1b[0m", dm = t.text_dim));
600	            }
601	
602	            line.push_str(&format!("  \x1b[{meta_col}m{id_short}  {ts}\x1b[0m"));
603	
604	            super::render_row(&mut buf, &line, i == sel, row, w)?;
605	            row += 1;
606	        }
607	    }
608	
609	    while row < content_h {
610	        queue!(buf, cursor::MoveTo(0, row as u16), terminal::Clear(ClearType::UntilNewLine))?;
611	        row += 1;
612	    }
613	
614	    let base = format!(
615	        "  {} sessions   ↑↓/jk navigate   space: view   r: resume   d: delete   s: launch   n: new worktree   t: tidy   / search   ←/h: back   q: quit  ",
616	        sessions.len()
617	    );
618	    let bar = if let Some(msg) = flash {
619	        let skip = msg.chars().count();
620	        let rest: String = base.chars().skip(skip).collect();
621	        format!("{msg}{rest}")
622	    } else { base };
623	    super::draw_statusbar(&mut buf, &bar, w, h)?;
624	
625	    stdout.write_all(&buf)?;
626	    stdout.flush()
627	}
