629	// ── Worktree loading ──────────────────────────────────────────────────────────
630	
631	fn fetch_worktrees(repo_dir: &str) -> Vec<RepoWorktree> {
632	    let out = std::process::Command::new("git")
633	        .args(["worktree", "list", "--porcelain"])
634	        .current_dir(repo_dir)
635	        .output();
636	
637	    let Ok(out) = out else { return vec![]; };
638	    if !out.status.success() { return vec![]; }
639	    let text = String::from_utf8_lossy(&out.stdout);
640	
641	    let mut result = Vec::new();
642	    let mut first = true;
643	
644	    // Each worktree block is separated by a blank line.
645	    for block in text.split("\n\n") {
646	        let mut path = String::new();
647	        let mut head = String::new();
648	        let mut branch = String::new();
649	        let mut detached = false;
650	
651	        for line in block.lines() {
652	            if let Some(v) = line.strip_prefix("worktree ") {
653	                path = v.to_string();
654	            } else if let Some(v) = line.strip_prefix("HEAD ") {
655	                head = v.chars().take(8).collect();
656	            } else if let Some(v) = line.strip_prefix("branch refs/heads/") {
657	                branch = v.to_string();
658	            } else if line == "detached" {
659	                detached = true;
660	            }
661	        }
662	
663	        if path.is_empty() { continue; }
664	        if detached { branch = "(detached)".to_string(); }
665	        if branch.is_empty() { continue; } // bare worktree — skip
666	
667	        result.push(RepoWorktree { path, branch, head, is_main: first });
668	        first = false;
669	    }
670	
671	    result
672	}
