677	
678	// ── New session wizard ────────────────────────────────────────────────────────
679	
680	/// A 3-step panel drawn over the bottom of the screen. Each completed step
681	/// stays visible with its confirmed value while the user fills the next one.
682	/// The prompt field (step 2) wraps across PROMPT_ROWS lines.
683	pub(super) fn new_session_wizard(stdout: &mut impl Write, repo_dir: &str, w: usize, h: usize) -> Option<NewSessionConfig> {
684	    const LABEL_W: usize = 24;
685	    const PROMPT_ROWS: usize = 3;
686	    // Panel: title + blank + branch + name + PROMPT_ROWS + blank
687	    const PANEL_H: usize = 4 + PROMPT_ROWS + 1;
688	
689	    let t = crate::theme::get();
690	    let panel_top = h.saturating_sub(PANEL_H + 1);
691	    let input_w = w.saturating_sub(LABEL_W).max(1);
692	
693	    let mut step = 0usize; // 0=branch 1=name 2=prompt
694	    let mut inputs = [String::new(), String::new(), String::new()];
695	
696	    execute!(stdout, cursor::Show).ok();
697	
698	    loop {
699	        // ── Draw panel ────────────────────────────────────────────────────────
700	        execute!(stdout, cursor::MoveTo(0, panel_top as u16)).ok();
701	        write!(stdout, "\x1b[{hd}m  Launch\x1b[0m", hd = t.header).ok();
702	        execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
703	
704	        execute!(stdout, cursor::MoveTo(0, (panel_top + 1) as u16)).ok();
705	        execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
706	
707	        let step_rows   = [panel_top + 2, panel_top + 3, panel_top + 4];
708	        let step_labels = ["  Worktree branch", "  Session name", "  Prompt"];
709	
710	        for (i, (&row, &label)) in step_rows.iter().zip(step_labels.iter()).enumerate() {
711	            let lpart = format!("{label:<LABEL_W$}");
712	
713	            if i == 2 {
714	                // Multi-row prompt area: show the tail end that fits in PROMPT_ROWS lines.
715	                let max_visible = PROMPT_ROWS * input_w;
716	                let chars: Vec<char> = inputs[i].chars().collect();
717	                let display_start = chars.len().saturating_sub(max_visible);
718	                let display_chars: Vec<char> = chars[display_start..].to_vec();
719	
720	                for pr in 0..PROMPT_ROWS {
721	                    execute!(stdout, cursor::MoveTo(0, (row + pr) as u16)).ok();
722	                    let chunk: String = display_chars.iter().skip(pr * input_w).take(input_w).collect();
723	                    let indent = if pr == 0 { lpart.clone() } else { " ".repeat(LABEL_W) };
724	
725	                    if i < step {
726	                        if pr == 0 && inputs[i].is_empty() {
727	                            write!(stdout, "\x1b[{dm}m{indent}\x1b[{ft}m(skip)\x1b[0m",
728	                                dm = t.text_dim, ft = t.text_faint).ok();
729	                        } else {
730	                            write!(stdout, "\x1b[{dm}m{indent}\x1b[{pm}m{chunk}\x1b[0m",
731	                                dm = t.text_dim, pm = t.text_primary).ok();
732	                        }
733	                    } else if i == step {
734	                        write!(stdout, "\x1b[{pm}m{indent}{chunk}\x1b[0m", pm = t.text_primary).ok();
735	                    } else if pr == 0 {
736	                        write!(stdout, "\x1b[{ft}m{indent}\x1b[0m", ft = t.text_faint).ok();
737	                    }
738	                    execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
739	                }
740	                continue;
741	            }
742	
743	            execute!(stdout, cursor::MoveTo(0, row as u16)).ok();
744	            if i < step {
745	                let v = inputs[i].trim();
746	                let val = if v.is_empty() {
747	                    format!("\x1b[{ft}m(skip)\x1b[0m", ft = t.text_faint)
748	                } else {
749	                    format!("\x1b[{pm}m{v}\x1b[0m", pm = t.text_primary)
750	                };
751	                write!(stdout, "\x1b[{dm}m{lpart}\x1b[0m{val}", dm = t.text_dim).ok();
752	            } else if i == step {
753	                write!(stdout, "\x1b[{pm}m{lpart}\x1b[0m", pm = t.text_primary).ok();
754	                write!(stdout, "\x1b[{pm}m{}\x1b[0m", inputs[i], pm = t.text_primary).ok();
755	            } else {
756	                write!(stdout, "\x1b[{ft}m{lpart}\x1b[0m", ft = t.text_faint).ok();
757	            }
758	            execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
759	        }
760	
761	        let blank2 = panel_top + 4 + PROMPT_ROWS;
762	        if blank2 < h.saturating_sub(1) {
763	            execute!(stdout, cursor::MoveTo(0, blank2 as u16)).ok();
764	            execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
765	        }
766	
767	        super::draw_statusbar(stdout, "  type to enter   enter: next   esc: cancel  ", w, h).ok();
768	
769	        // ── Position cursor ───────────────────────────────────────────────────
770	        if step == 2 {
771	            let max_visible = PROMPT_ROWS * input_w;
772	            let display_len = inputs[step].chars().count().min(max_visible);
773	            let (row_off, col) = if display_len / input_w >= PROMPT_ROWS {
774	                (PROMPT_ROWS - 1, LABEL_W + input_w)
775	            } else {
776	                (display_len / input_w, LABEL_W + display_len % input_w)
777	            };
778	            execute!(stdout, cursor::MoveTo(
779	                col.min(w.saturating_sub(1)) as u16,
780	                (step_rows[2] + row_off) as u16,
781	            )).ok();
782	        } else {
783	            let col = (LABEL_W + inputs[step].len()).min(w.saturating_sub(1));
784	            execute!(stdout, cursor::MoveTo(col as u16, step_rows[step] as u16)).ok();
785	        }
786	        stdout.flush().ok();
787	
788	        // ── Handle input ──────────────────────────────────────────────────────
789	        match event::read().ok()? {
790	            Event::Key(k) => match k.code {
791	                KeyCode::Esc => {
792	                    execute!(stdout, cursor::Hide).ok();
793	                    return None;
794	                }
795	                KeyCode::Backspace => { inputs[step].pop(); }
796	                KeyCode::Char(c) if !k.modifiers.contains(crossterm::event::KeyModifiers::CONTROL) => {
797	                    inputs[step].push(c);
798	                }
799	                KeyCode::Enter => match step {
800	                    0 | 1 => { step += 1; }
801	                    _ => {
802	                        execute!(stdout, cursor::Hide).ok();
803	                        let branch_raw = inputs[0].trim().to_string();
804	                        return Some(NewSessionConfig {
805	                            branch: if branch_raw.is_empty() { None } else { Some(branch_raw) },
806	                            session_name: inputs[1].trim().to_string(),
807	                            prompt: inputs[2].trim().to_string(),
808	                            repo_dir: repo_dir.to_string(),
809	                        });
810	                    }
811	                },
812	                _ => {}
813	            },
814	            _ => {}
815	        }
816	    }
817	}
