821	/// Create the worktree (if `cfg.branch` is set), copy the prompt to the
822	/// clipboard, then `exec` claude. Only returns if `exec` failed.
823	pub(super) fn launch_new_session(cfg: NewSessionConfig) {
824	    use std::os::unix::process::CommandExt;
825	
826	    let launch_dir = if let Some(ref branch) = cfg.branch {
827	        let _ = create_worktree(&cfg.repo_dir, branch);
828	        let repo_path = std::path::Path::new(&cfg.repo_dir);
829	        let parent = repo_path.parent().unwrap_or(repo_path);
830	        let repo_name = repo_path.file_name()
831	            .map(|s| s.to_string_lossy().to_string())
832	            .unwrap_or_else(|| "repo".to_string());
833	        parent.join(format!("{repo_name}-{}", branch)).to_string_lossy().to_string()
834	    } else {
835	        cfg.repo_dir.clone()
836	    };
837	
838	    let prompt = cfg.prompt.trim().to_string();
839	    if !prompt.is_empty() {
840	        if let Ok(mut child) = std::process::Command::new("pbcopy")
841	            .stdin(std::process::Stdio::piped())
842	            .spawn()
843	        {
844	            if let Some(stdin) = child.stdin.as_mut() {
845	                let _ = stdin.write_all(prompt.as_bytes());
846	            }
847	            let _ = child.wait();
848	        }
849	    }
850	
851	    let session_name = cfg.session_name.trim().to_string();
852	    let mut cmd = std::process::Command::new("claude");
853	    if !launch_dir.is_empty() { cmd.current_dir(&launch_dir); }
854	    if !session_name.is_empty() { cmd.args(["-n", &session_name]); }
855	    if !prompt.is_empty() { cmd.arg(&prompt); }
856	    let err = cmd.exec();
857	    eprintln!("Failed to launch claude: {err}");
858	}
