860	pub(super) fn create_worktree(repo_dir: &str, branch: &str) -> String {
861	    let repo_path = std::path::Path::new(repo_dir);
862	    let parent = match repo_path.parent() {
863	        Some(p) => p,
864	        None => return "Error: cannot determine repo parent directory".to_string(),
865	    };
866	    let repo_name = repo_path
867	        .file_name()
868	        .map(|s| s.to_string_lossy().to_string())
869	        .unwrap_or_else(|| "repo".to_string());
870	    let wt_path = parent.join(format!("{repo_name}-{branch}"));
871	
872	    // Try -b (new branch) first; fall back to checking out an existing branch.
873	    let out = std::process::Command::new("git")
874	        .args(["worktree", "add", "-b", branch, wt_path.to_str().unwrap_or("")])
875	        .current_dir(repo_dir)
876	        .output();
877	
878	    match out {
879	        Err(e) => format!("Error: {e}"),
880	        Ok(o) if o.status.success() => {
881	            format!("Created worktree: {}", super::short_path(wt_path.to_str().unwrap_or("")))
882	        }
883	        Ok(o) => {
884	            let msg = String::from_utf8_lossy(&o.stderr);
885	            let first = msg.lines().find(|l| !l.trim().is_empty()).unwrap_or("unknown error");
886	            format!("Error: {first}")
887	        }
888	    }
889	}
