892	// Find which tracked repo the current directory belongs to — handles both the
893	// main worktree (starts_with match) and linked worktrees (git-common-dir match).
894	fn find_repo_for_cwd(repos: &[Repository]) -> Option<usize> {
895	    let cwd = env::current_dir().ok()?;
896	    let cwd_str = cwd.to_string_lossy();
897	
898	    // Main worktree: cwd is inside the repo root
899	    if let Some(idx) = repos.iter().position(|r| cwd_str.starts_with(r.directory.as_str())) {
900	        return Some(idx);
901	    }
902	
903	    // Linked worktree: git-common-dir points to the main repo's .git
904	    let out = std::process::Command::new("git")
905	        .args(["rev-parse", "--git-common-dir"])
906	        .current_dir(&cwd)
907	        .output()
908	        .ok()?;
909	    if !out.status.success() { return None; }
910	
911	    let common = String::from_utf8_lossy(&out.stdout).trim().to_string();
912	    let common_path = if std::path::Path::new(&common).is_absolute() {
913	        std::path::PathBuf::from(&common)
914	    } else {
915	        cwd.join(&common)
916	    };
917	
918	    // common_path is the .git dir; its parent is the repo root
919	    let repo_root = common_path.parent()?.to_string_lossy().to_string();
920	    repos.iter().position(|r| r.directory == repo_root)
921	}
