924	fn relative_time(dt: DateTime<Utc>) -> String {
925	    let secs = (Utc::now() - dt).num_seconds().max(0);
926	    if secs < 604_800 {
927	        match secs {
928	            s if s < 60     => "just now".to_string(),
929	            s if s < 3_600  => format!("{} min{} ago", s/60,     if s/60==1     {""} else {"s"}),
930	            s if s < 86_400 => format!("{} hr{} ago",  s/3_600,  if s/3_600==1  {""} else {"s"}),
931	            s               => format!("{} day{} ago", s/86_400, if s/86_400==1 {""} else {"s"}),
932	        }
933	    } else {
934	        dt.with_timezone(&Local).format("%m/%d/%y").to_string()
935	    }
936	}
