938	pub fn run_for_dir(repo_dir: &str) -> Result<bool> {
939	    let conn = db::connect()?;
940	    let mut repos = fetch_repos(&conn)?;
941	    let start = repos.iter().position(|r| r.directory == repo_dir);
942	
943	    let orig_hook = std::panic::take_hook();
944	    std::panic::set_hook(Box::new(move |info| {
945	        let mut out = io::stdout();
946	        let _ = execute!(out, LeaveAlternateScreen, cursor::Show);
947	        let _ = terminal::disable_raw_mode();
948	        orig_hook(info);
949	    }));
950	
951	    let mut stdout = io::stdout();
952	    terminal::enable_raw_mode()?;
953	    execute!(stdout, EnterAlternateScreen, cursor::Hide)?;
954	
955	    let outcome = tui_loop(&mut stdout, &mut repos, false, start);
956	
957	    execute!(stdout, LeaveAlternateScreen, cursor::Show)?;
958	    terminal::disable_raw_mode()?;
959	
960	    let outcome = outcome?;
961	    let quit_app = matches!(outcome, Some(TuiOutcome::Quit));
962	    match outcome {
963	        Some(TuiOutcome::ResumeSession { id, cwd }) => {
964	            super::show::resume_session(&id, &cwd);
965	        }
966	        Some(TuiOutcome::LaunchNewSession(cfg)) => { launch_new_session(cfg); }
967	        _ => {}
968	    }
969	
970	    Ok(quit_app)
971	}
