973	pub fn fetch_repos(conn: &rusqlite::Connection) -> Result<Vec<Repository>> {
974	    let mut stmt = conn.prepare("SELECT id, directory, remote, name FROM repositories ORDER BY name")?;
975	    let repos = stmt.query_map([], |row| {
976	        Ok(Repository {
977	            id: row.get(0)?,
978	            directory: row.get(1)?,
979	            remote: row.get(2)?,
980	            name: row.get(3)?,
981	        })
982	    })?
983	    .collect::<Result<Vec<_>, _>>()?;
984	    Ok(repos)
985	}
