91	pub enum Scope<'a> {
92	    /// All tracked sessions across every repo.
93	    All,
94	    /// Sessions belonging to a single repo. Matched primarily by `repo_id`;
95	    /// older rows without `repo_id` are caught by `cwd LIKE <directory>%`.
96	    Repo(&'a Repository),
97	}
98	
99	/// Load sessions, optionally scoped to one repo. With `include_old = false`,
100	/// returns the 10 most-recent sessions. Result is sorted most-recent-first;
101	/// callers are free to re-sort.
102	pub fn fetch(scope: Scope, include_old: bool) -> Vec<DisplaySession> {
103	    let mut sessions = query_db(&scope);
104	    augment_with_jsonls(&mut sessions, &scope);
105	    sessions.sort_by(|a, b| b.updated_at.cmp(&a.updated_at));
106	    if !include_old {
107	        sessions.truncate(10);
108	    }
109	    sessions
110	}
111	
112	fn query_db(scope: &Scope) -> Vec<DisplaySession> {
113	    let Ok(conn) = db::connect() else { return Vec::new(); };
114	    let mut out: Vec<DisplaySession> = Vec::new();
115	    let map = |row: &rusqlite::Row<'_>| -> rusqlite::Result<DisplaySession> {
116	        let ts: String = row.get(4)?;
117	        let author_name: String = row.get(6)?;
118	        let author_email: String = row.get(7)?;
119	        let os_user: String = row.get(8)?;
120	        let raw_name: String = row.get(1)?;
121	        let name_is_explicit: i64 = row.get(9)?;
122	        let tokens_used: i64 = row.get(10)?;
123	        Ok(DisplaySession {
124	            session_id: row.get(0)?,
125	            session_name: sanitize_one_line(&raw_name),
126	            cwd: row.get(2)?,
127	            branch: row.get(3)?,
128	            updated_at: DateTime::parse_from_rfc3339(&ts)
129	                .map(|dt| dt.with_timezone(&Utc))
130	                .unwrap_or_else(|_| Utc::now()),
131	            agent_name: row.get(5)?,
132	            backed_up: true,
133	            author: resolve_author_label(&author_name, &author_email, &os_user),
134	            name_is_explicit: name_is_explicit != 0,
135	            tokens_used,
136	        })
137	    };
138	    // Pull the author of the FIRST checkpoint (lowest checkpoint_number) for
139	    // each session — that's whoever initiated the first message. Sessions
140	    // without checkpoints (shadow-only) get NULLs which COALESCE turns into
141	    // empty strings, leaving `author` blank.
142	    let cols = "
143	        s.session_id, s.session_name, s.cwd, COALESCE(s.branch,''),
144	        s.updated_at, s.agent_name,
145	        COALESCE(c.author_name, ''), COALESCE(c.author_email, ''), COALESCE(c.os_user, ''),
146	        s.name_is_explicit, COALESCE(s.tokens_used, 0)
147	    ";
148	    let join = "
149	        LEFT JOIN checkpoints c
150	          ON c.session_id = s.session_id
151	         AND c.checkpoint_id = (
152	               SELECT checkpoint_id FROM checkpoints
153	               WHERE session_id = s.session_id
154	               ORDER BY last_turn_ts ASC
155	               LIMIT 1
156	             )
157	    ";
158	    match scope {
159	        Scope::All => {
160	            let Ok(mut stmt) = conn.prepare(
161	                &format!("SELECT {cols} FROM sessions s {join} ORDER BY s.updated_at DESC")
162	            ) else { return out; };
163	            if let Ok(rows) = stmt.query_map([], map) {
164	                for r in rows.flatten() { out.push(r); }
165	            }
166	        }
167	        Scope::Repo(r) => {
168	            let Ok(mut stmt) = conn.prepare(&format!(
169	                "SELECT {cols} FROM sessions s {join}
170	                 WHERE s.repo_id = ?1 OR (s.repo_id IS NULL AND s.cwd LIKE ?2)
171	                 ORDER BY s.updated_at DESC"
172	            )) else { return out; };
173	            let pattern = format!("{}%", r.directory);
174	            if let Ok(rows) = stmt.query_map(rusqlite::params![r.id as i64, pattern], map) {
175	                for row in rows.flatten() { out.push(row); }
176	            }
177	        }
178	    }
179	    out
180	}
