182	fn cwd_os_user(cwd: &str) -> Option<String> {
183	    let rest = cwd.strip_prefix("/Users/").or_else(|| cwd.strip_prefix("/home/"))?;
184	    let user = rest.split('/').next()?;
185	    if user.is_empty() { None } else { Some(user.to_string()) }
186	}
