188	fn resolve_author_label(name: &str, email: &str, os_user: &str) -> String {
189	    if !name.trim().is_empty() { return name.to_string(); }
190	    if !email.trim().is_empty() { return email.to_string(); }
191	    if !os_user.trim().is_empty() { return os_user.to_string(); }
192	    String::new()
