194	
195	fn augment_with_jsonls(
196	    sessions: &mut Vec<DisplaySession>,
197	    scope: &Scope,
198	) {
199	    let Ok(home) = std::env::var("HOME") else { return; };
200	    let projects = PathBuf::from(&home).join(".claude/projects");
201	    let Ok(dirs) = std::fs::read_dir(&projects) else { return; };
202	
203	    for dir_entry in dirs.flatten() {
204	        let dir = dir_entry.path();
205	        if !dir.is_dir() { continue }
206	        let Ok(files) = std::fs::read_dir(&dir) else { continue };
207	        for f in files.flatten() {
208	            let path = f.path();
209	            if path.extension().and_then(|e| e.to_str()) != Some("jsonl") { continue }
210	            let Some(session_id) = path.file_stem().and_then(|s| s.to_str()).map(str::to_string)
211	                else { continue };
212	
213	            let file_mtime = f.metadata().ok()
214	                .and_then(|m| m.modified().ok())
215	                .map(DateTime::<Utc>::from)
216	                .unwrap_or_else(Utc::now);
217	
218	            let parsed = parse_jsonl(&path);
219	
220	            if let Some(existing) = sessions.iter_mut().find(|s| s.session_id == session_id) {
221	                if !parsed.session_name.is_empty() { existing.session_name = parsed.session_name; }
222	                if file_mtime > existing.updated_at { existing.updated_at = file_mtime; }
223	                if !parsed.branch.is_empty() { existing.branch = parsed.branch; }
224	                // A custom-title in the JSONL outranks the DB flag. Without
225	                // this, /rename'd sessions stay tagged as "derived" until the
226	                // next index run, so they render gray in the lists.
227	                if parsed.name_is_explicit { existing.name_is_explicit = true; }
228	                // JSONL token count is authoritative when present (live data).
229	                if parsed.tokens_used > 0 { existing.tokens_used = parsed.tokens_used; }
230	                // Sessions inserted by the SessionStart hook but never indexed
231	                // from a checkpoint branch have no `checkpoints` row, so the
232	                // author column came back empty. Fall back to the cwd's
233	                // os-user — same fallback used for brand-new untracked rows.
234	                if existing.author.is_empty() {
235	                    let cwd = if !existing.cwd.is_empty() { existing.cwd.as_str() } else { parsed.cwd.as_str() };
236	                    existing.author = cwd_os_user(cwd).unwrap_or_default();
237	                }
238	                continue;
239	            }
240	
241	            // Untracked session (only in local JSONL). When scoped to one
242	            // repo, only include if its cwd actually belongs to that repo.
243	            if let Scope::Repo(r) = scope {
244	                if !parsed.cwd.starts_with(r.directory.as_str()) { continue }
245	            }
246	
247	            let author = cwd_os_user(&parsed.cwd).unwrap_or_default();
248	            sessions.push(DisplaySession {
249	                session_id,
250	                session_name: parsed.session_name,
251	                cwd: parsed.cwd,
252	                branch: parsed.branch,
253	                updated_at: file_mtime,
254	                agent_name: "Claude Code".to_string(),
255	                backed_up: false,
256	                author,
257	                name_is_explicit: parsed.name_is_explicit,
258	                tokens_used: parsed.tokens_used,
259	            });
260	        }
261	    }
262	}
263	
264	struct ParsedJsonl {
265	    session_name: String,
266	    cwd: String,
267	    branch: String,
268	    name_is_explicit: bool,
269	    tokens_used: i64,
270	}
271	
272	fn parse_jsonl(path: &Path) -> ParsedJsonl {
273	    let mut out = ParsedJsonl {
274	        session_name: String::new(),
275	        cwd: String::new(),
276	        branch: String::new(),
277	        name_is_explicit: false,
278	        tokens_used: 0,
279	    };
280	    let Ok(file) = std::fs::File::open(path) else { return out; };
281	    let reader = std::io::BufReader::new(file);
282	    let mut last_prompt = String::new();
283	    let mut custom_title = String::new();
284	
285	    for line in reader.lines().flatten() {
286	        let Ok(v) = serde_json::from_str::<serde_json::Value>(&line) else { continue };
287	        match v["type"].as_str() {
288	            Some("custom-title") => {
289	                if let Some(t) = v["customTitle"].as_str() {
290	                    if !t.trim().is_empty() { custom_title = t.to_string(); }
291	                }
292	            }
293	            Some("user") | Some("system") => {
294	                if out.cwd.is_empty() {
295	                    if let Some(c) = v["cwd"].as_str() { out.cwd = c.to_string(); }
296	                }
297	            }
298	            Some("assistant") => {
299	                if let Some(n) = v["message"]["usage"]["output_tokens"].as_i64() {
300	                    out.tokens_used += n;
301	                }
302	            }
303	            _ => {}
304	        }
305	        if v["type"].as_str() == Some("user") {
306	            if let Some(t) = user_text(&v["message"]["content"]) {
307	                last_prompt = t;
308	            }
309	        }
310	        if let Some(b) = v["gitBranch"].as_str() {
311	            if !b.is_empty() { out.branch = b.to_string(); }
312	        }
313	    }
314	    if !custom_title.is_empty() {
315	        out.session_name = custom_title;
316	        out.name_is_explicit = true;
317	    } else {
318	        out.session_name = last_prompt;
319	    }
320	    out.session_name = sanitize_one_line(&out.session_name);
321	    out
322	}
323	
324	fn user_text(content: &serde_json::Value) -> Option<String> {
325	    match content {
326	        serde_json::Value::String(s) if !s.trim().is_empty() => Some(s.trim().to_string()),
327	        serde_json::Value::Array(blocks) => {
328	            blocks.iter().find_map(|b| {
329	                if b["type"].as_str() == Some("text") {
330	                    b["text"].as_str().filter(|t| !t.trim().is_empty()).map(|t| t.trim().to_string())
331	                } else { None }
332	            })
333	        }
334	        _ => None,
335	    }
336	}
