import os, pty, sys, time, re, select

session_id = sys.argv[1]
keys = sys.argv[2:]

pid, fd = pty.fork()
if pid == 0:
    os.execvp("entire-gossamer", ["entire-gossamer", "show", session_id])
else:
    def read_available(timeout=0.6):
        buf = b""
        while True:
            r, _, _ = select.select([fd], [], [], timeout)
            if not r:
                break
            try:
                chunk = os.read(fd, 65536)
            except OSError:
                break
            if not chunk:
                break
            buf += chunk
        return buf

    time.sleep(0.5)
    out = read_available()
    print("=== initial ===")
    print(out.decode(errors="replace"))

    for k in keys:
        if k == "ENTER":
            os.write(fd, b"\r")
        elif k == "SPACE":
            os.write(fd, b" ")
        elif k == "DOWN":
            os.write(fd, b"\x1b[B")
        elif k == "UP":
            os.write(fd, b"\x1b[A")
        else:
            os.write(fd, k.encode())
        time.sleep(0.3)
        out = read_available()
        print(f"=== after {k} ===")
        print(out.decode(errors="replace"))

    os.write(fd, b"q")
    time.sleep(0.2)
    try:
        os.kill(pid, 9)
    except Exception:
        pass

import os, pty, sys, time, select, struct, fcntl, termios
import pyte

session_id = sys.argv[1]
keys = sys.argv[2:]

ROWS, COLS = 40, 160

screen = pyte.Screen(COLS, ROWS)
stream = pyte.Stream(screen)

pid, fd = pty.fork()
if pid == 0:
    os.execvp("entire-gossamer", ["entire-gossamer", "show", session_id])
else:
    # set window size
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", ROWS, COLS, 0, 0))
    os.kill(pid, 28)  # SIGWINCH

    def pump(duration=0.8):
        end = time.time() + duration
        while time.time() < end:
            r, _, _ = select.select([fd], [], [], 0.1)
            if r:
                try:
                    chunk = os.read(fd, 65536)
                except OSError:
                    break
                if not chunk:
                    break
                stream.feed(chunk.decode(errors="replace"))

    def dump(label):
        print(f"\n=== {label} ===")
        for line in screen.display:
            print(line.rstrip())

    pump(1.0)
    dump("initial")

    for k in keys:
        if k == "ENTER":
            os.write(fd, b"\r")
        elif k == "SPACE":
            os.write(fd, b" ")
        elif k == "DOWN":
            os.write(fd, b"\x1b[B")
        elif k == "UP":
            os.write(fd, b"\x1b[A")
        else:
            os.write(fd, k.encode())
        pump(0.5)
        dump(f"after {k}")

    os.write(fd, b"q")
    time.sleep(0.2)
    try:
        os.kill(pid, 9)
    except Exception:
        pass

